    static func questions(for topicCode: String, difficulty: DrillDifficulty? = nil) -> [MathDrillQuestion] {
        allQuestions.filter { q in
            q.topicCode == topicCode && (difficulty == nil || q.difficulty == difficulty)
        }
    }

    static func randomQuestion(for topicCode: String, difficulty: DrillDifficulty) -> MathDrillQuestion? {
        questions(for: topicCode, difficulty: difficulty).randomElement()
    }
